import Foundation
import Testing
import TranscriberCore
@testable import TranscriptionPipeline

/// Cases generated by Tools/parity/make_postprocessing_fixture.py, which runs the
/// original create_contiguous_chunks on the same speech spans.
struct ChunkPlannerTests {
    @Test(arguments: try ChunkFixture.load().cases)
    func matchesOriginalChunking(_ testCase: ChunkFixture.Case) {
        let spans = testCase.speechSpans.map {
            SpeechSpan(start: AudioTime(samples: $0.start), end: AudioTime(samples: $0.end))
        }
        let chunks = ChunkPlanner.contiguousChunks(
            speech: spans,
            totalDurationSeconds: Double(testCase.totalSamples) / Double(AudioTime.sampleRate),
            maximumDurationSeconds: ChickenRiceDefaults.chunking.targetChunkDurationSeconds,
            splitWindowFactor: ChickenRiceDefaults.chunking.splitWindowFactor
        )
        let expected = testCase.expectedChunks.enumerated().map {
            AudioChunk(index: $0.offset, startSeconds: $0.element.start, endSeconds: $0.element.end)
        }
        #expect(chunks == expected, "\(testCase.name)")
    }

    @Test func shortAudioIsOneChunk() {
        let chunks = ChunkPlanner.contiguousChunks(
            speech: [], totalDurationSeconds: 12, maximumDurationSeconds: 30, splitWindowFactor: 0.4
        )
        #expect(chunks == [AudioChunk(index: 0, startSeconds: 0, endSeconds: 12)])
    }
}

struct ChunkFixture: Decodable {
    struct Case: Decodable, Sendable, CustomTestStringConvertible {
        let name: String
        let totalSamples: Int
        let speechSpans: [SampleSpan]
        let expectedChunks: [SecondsSpan]

        var testDescription: String { name }
    }

    struct SampleSpan: Decodable, Sendable {
        let start: Int
        let end: Int
    }

    struct SecondsSpan: Decodable, Sendable {
        let start: Double
        let end: Double
    }

    let cases: [Case]

    static func load() throws -> ChunkFixture {
        let url = try #require(Bundle.module.url(forResource: "chunk-cases", withExtension: "json", subdirectory: "Fixtures"))
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ChunkFixture.self, from: Data(contentsOf: url))
    }
}
